struct FieldKey
{
    uint32_t msgid;
    std::string field;
    bool operator==(const FieldKey &other) const
    {
        return msgid == other.msgid && field == other.field;
    }
};

struct FieldKeyHash
{
    std::size_t operator()(const FieldKey &k) const
    {
        return std::hash<uint32_t>()(k.msgid) ^ (std::hash<std::string>()(k.field) << 1);
    }
};

