std::string fieldEnumType(uint32_t msgid, const std::string &fieldName)
{
    const auto &map = fieldToEnumMap();
    const auto it = map.find({msgid, fieldName});
    return it != map.end() ? it->second : std::string();
}

const std::vector<EnumEntry> &enumEntries(const std::string &enumName)
{
    static const std::vector<EnumEntry> empty;
    const auto &defs = enumDefinitions();
    const auto it = defs.find(enumName);
    return it != defs.end() ? it->second : empty;
}

const std::vector<EnumEntry> &fieldEnumEntries(uint32_t msgid, const std::string &fieldName)
{
    const std::string type = fieldEnumType(msgid, fieldName);
    return enumEntries(type);
}

std::optional<uint64_t> lookupEnumValue(const std::string &symbol)
{
    if (symbol.empty())
    {
        return std::nullopt;
    }
    // Clean leading/trailing spaces
    const auto first = symbol.find_first_not_of(" \t\r\n");
    if (first == std::string::npos)
    {
        return std::nullopt;
    }
    const auto last = symbol.find_last_not_of(" \t\r\n");
    std::string clean = symbol.substr(first, last - first + 1);
    // Handle formats like "MAV_PARAM_TYPE_REAL32 (9)" or "MAV_PARAM_TYPE_REAL32"
    const auto paren = clean.find('(');
    if (paren != std::string::npos)
    {
        clean = clean.substr(0, paren);
        const auto endTrim = clean.find_last_not_of(" \t\r\n");
        if (endTrim != std::string::npos)
        {
            clean = clean.substr(0, endTrim + 1);
        }
    }
    const auto &symbols = symbolMap();
    const auto it = symbols.find(clean);
    if (it != symbols.end())
    {
        return it->second;
    }
    return std::nullopt;
}

std::string lookupEnumNameByType(const std::string &enumName, uint64_t value)
{
    const auto &entries = enumEntries(enumName);
    for (const auto &entry : entries)
    {
        if (entry.value == value)
        {
            return entry.name;
        }
    }
    return {};
}

std::string lookupEnumName(uint32_t msgid, const std::string &fieldName, uint64_t value)
{
    const std::string type = fieldEnumType(msgid, fieldName);
    return lookupEnumNameByType(type, value);
}

